<script setup>
import { computed, ref } from 'vue'
import { Mountain, Database, FileSearch, Network, Map, Search, Handshake, Settings, ChevronDown, ChevronRight, Bell, CircleHelp, PanelLeftClose, LayoutDashboard, MapPin, MoreHorizontal, Activity } from 'lucide-vue-next'
import OverviewPage from './components/OverviewPage.vue'
import ResourceLibraryPage from './components/ResourceLibraryPage.vue'
