import PlaceholderPage from './components/PlaceholderPage.vue'
import MapDistributionPage from './components/MapDistributionPage.vue'
import ResourceAskPage from './components/ResourceAskPage.vue'
const active=ref('概览'),expanded=ref('供需智能对接')
const navGroups=[
{name:'资源管理',icon:Database,children:['东盟资源库','资源信息录入',/*'资源信息审核'*/]},{name:'语料抽取',icon:FileSearch,children:['多模态语料接入','构建向量知识库','抽取结果消解']},{name:'知识图谱',icon:Network,children:['多模态知识图谱','知识融合与补全']},{name:'资源分布监测',icon:Activity,children:['区域空间概况','供需分布监测','缺失数据管理']},{name:'地图可视化',icon:Map,children:['资源分布图','供需热力图','资源禀赋分析']},{name:'资源查询',icon:Search,children:['资源需求智能问答','资源目录查询','图谱关系查询']},{name:'供需智能对接',icon:Handshake,children:['需求语义解析','双向智能匹配','潜在合作方推荐']},{name:'系统管理',icon:Settings,children:['用户与权限','操作日志','系统设置']}]
const setPage=(page,group)=>{active.value=page;if(group)expanded.value=group}
const isMatching=computed(()=>['需求语义解析','双向智能匹配','潜在合作方推荐','企业供需知识图谱'].includes(active.value))
const isCorpus=computed(()=>['多模态语料接入','构建向量知识库','抽取结果消解'].includes(active.value))
const isGraph=computed(()=>['多模态知识图谱','知识融合与补全'].includes(active.value))
const isOverview=computed(()=>active.value==='概览')
const isLibrary=computed(()=>active.value==='东盟资源库')
const isMap=computed(()=>active.value==='资源分布图')
const isAsk=computed(()=>active.value==='资源需求智能问答')
const activeTitle=computed(()=>active.value)
const pageDescription=computed(()=>isOverview.value?'整合区域资源语料，构建可追溯的知识关系与供需协作网络。':isLibrary.value?'总览东盟多语种语料资源的库容、贡献分布与最新动态。':active.value==='资源信息录入'?'录入语料资源信息并上传附件，自动估算容量、校验名称查重。':isCorpus.value?'从公开资料与业务文档中提取实体关系，沉淀为可检索的资源知识。':active.value==='知识融合与补全'?'发现图谱缺口，检索语料证据并推断候选实体关系。':isGraph.value?'浏览广西与东盟国家的矿产资源、区域与产业需求关系。':isMatching.value?'解析企业需求，发现跨区域资源供需与潜在合作机会。':isAsk.value?'描述你的企业或需求，自动匹配广西与东盟的矿产与自然资源需求线索。':'查看广西及东盟各国资源信息与业务动态。')
</script>
<template>
